#!/bin/bash
# Builds refdata/apk/INDEX.md from _levels.tsv (scan) and _converted.tsv (convert). usage: bash index.sh
set -u; D="$(cd "$(dirname "$0")" && pwd)"; O="$D/../../refdata/apk"
label() { # scene path -> room / area
  case "$1" in
    */main_root.unity) echo "boot root (systems)";; */empty.unity) echo "empty";; */late_main_root.unity) echo "late boot root (systems)";;
    */TitleScreen.unity) echo "title screen";; */LogoutScene.unity) echo "logout";; */RecRoomStudioTerrainScene.unity) echo "Studio terrain shader pinning (tech)";;
    */dormroom2.unity) echo "Dorm Room (built-in, 2019 build stamp)";; */LockerRoom/Scenes/reccenter.unity) echo "Rec Center (built-in, older than the Studio one)";;
    */charades.unity) echo "Charades";; */discgolf.unity) echo "Disc Golf (Lake)";; */Discgolf_Propulsion.unity) echo "Disc Golf Propulsion";;
    */dodgeball.unity) echo "Dodgeball gym";; */eventroom.unity) echo "Event room";; */paddleball.unity) echo "Paddleball";;
    */River/paintball.unity) echo "Paintball: River";; */paintball2_open.unity) echo "Paintball: Homestead (Construction folder)";;
    */Paintball_Castle.unity) echo "Paintball: Quarry (Castle folder)";; */Paintball_ClearCut.unity) echo "Paintball: Clearcut";; */Paintball_Dam.unity) echo "Paintball: Spillway (Dam folder)";;
    */DriveIn.unity) echo "Paintball: Drive-In";; */MerryMidway.unity) echo "Paintball: Merry Midway";; */paintball_lobby.unity) echo "Paintball lobby";;
    */Goblin_1/*additive*) echo "Golden Trophy: additive (shared systems)";; */Goblin_1/*) b=$(basename "$1" .unity); echo "Golden Trophy: ${b#Quest_}";;
    */Scifi_1/*[Aa]dditive*) echo "Crescendo of Champions (Scifi_1): additive";; */Scifi_1/*) b=$(basename "$1" .unity); echo "Crescendo of Champions (Scifi_1): ${b#Quest_Scifi_}";;
    */Goblin_2/*additive*) echo "Curse of the Crimson Cauldron (Goblin_2): additive";; */Goblin_2/*) b=$(basename "$1" .unity); echo "Crimson Cauldron (Goblin_2): ${b#Quest_Goblin2_}";;
    */Pirate_1/*additive*) echo "Isle of Lost Skulls: additive";; */Pirate_1/*) b=$(basename "$1" .unity); echo "Isle of Lost Skulls: ${b#Quest_Pirate1_}";;
    */Dracula_1/*additive*) echo "Dracula quest (Dracula_1): additive";; */Dracula_1/*) b=$(basename "$1" .unity); echo "Dracula quest (Dracula_1): ${b#Quest_Dracula1_}";;
    */Orientation*) b=$(basename "$1" .unity); echo "Orientation: ${b#Orientation_}";; */soccer.unity) echo "Soccer";; */PerformanceHall.unity) echo "Performance Hall";;
    */room_calibration.unity) echo "room calibration";; */Park.unity) echo "Park";; */Arena_Hangar3.unity) echo "Laser Tag: Hangar";; */Arena_Cyberjunk_City.unity) echo "Laser Tag: Cyberjunk City";;
    */Basement.unity) echo "Basement (UGC base)";; */BowlingAlley.unity) echo "Bowling alley";; */StuntRunner_Lobby.unity) echo "Stunt Runner lobby";;
    */StuntRunner_Course*) b=$(basename "$1" .unity); echo "Stunt Runner ${b#StuntRunner_}";; */StuntRunner_additive.unity) echo "Stunt Runner additive";; */StuntRunner_Baseroom.unity) echo "Stunt Runner base room";;
    */registration.unity) echo "registration";; */AR_room.unity) echo "AR room (empty)";; */charades_theinkspace.unity) echo "Charades: The Ink Space";; */the_ink_space.unity) echo "The Ink Space";;
    */RecRally_Chaparral.unity) echo "Rec Rally: Chaparral";; */ugcr2.unity) echo "UGC R2 base";; */ugcdormroom.unity) echo "UGC Dorm Room base";; */ugcr2dormroom.unity) echo "UGC R2 Dorm Room base";;
    *) basename "$1" .unity;;
  esac
}
{
echo "# Android build levels (Rec Room 2026-03-23 XAPK, Unity 6000.0.27f1): index"
echo
echo "Generated by DevNotes/tools/apkscene (\`scan\` + \`convert\`, then \`index.sh\`). The level number is the BuildSettings index"
echo "from the base APK's globalgamemanagers (levelN = scene N). Renderers = active, enabled, LOD0 renderers with a mesh;"
echo "match = share whose mesh name is an install (PC bundle) Mesh; colliders = enabled non-trigger colliders on active objects."
echo "Converted levels list the numbers of their .rrsk (after P/G prefab grouping) and a verdict."
echo
echo "| level | scene | room / area | GOs | renderers | install-mesh match | colliders | terrain | file | verdict |"
echo "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |"
while IFS=$'\t' read -r lv sp gos rend match pct cols terr roots signs gs; do
  lab=$(label "$sp"); conv=$(awk -F'\t' -v l="$lv" 'BEGIN{OFS="|"} $1==l {$1=$1; print}' "$O/_converted.tsv" 2>/dev/null | head -1)
  if [ -n "$conv" ]; then
    IFS='|' read -r _ sc _ crend cmatch cpct ccols cmesh cmeas cbox cterr cp cg cx cval ckb <<< "$conv"
    v="layout + colliders; art mostly stand-ins"; awk "BEGIN{exit !($cpct>=90)}" && v="good: nearly all art loads from the install"; awk "BEGIN{exit !($cpct>=50 && $cpct<90)}" && v="usable: install art + stand-ins"
    case "$sc" in Paintball_*) [ -n "$cval" ] && v="$v; frame check: $cval";; esac
    [ "$crend" = "0" ] && v="nothing to place (systems only)"
    echo "| $lv | \`${sp##*/}\` | $lab | $gos | $crend | $cmatch ($cpct%) | $ccols (mesh $cmesh, measured $cmeas) | $cterr | [$sc.rrsk]($sc.rrsk) ${ckb} KB | $v |"
  else
    echo "| $lv | \`${sp##*/}\` | $lab | $gos | $rend | $match ($pct%) | $cols | $terr | - | not converted |"
  fi
done < "$O/_levels.tsv"
echo
echo "Missing from the Android build (no level): Rec Royale, Showdown, the final Studio Rec Center and the final Dorm (those are"
echo "Addressables/UGC rooms, not built-in scenes). Golden Trophy acts in refdata/ (GTact1..6) come from the Studio archive; the"
echo "Android Golden Trophy is the older room-per-scene layout (Foyer .. Cafeteria)."
} > "$O/INDEX.md"
wc -l "$O/INDEX.md"
